// Runnable demo showing the four JVM memory areas in action.
public class MemoryDemo {
    private static final Logger log = Logger.getLogger(MemoryDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MemoryInspector inspector = new MemoryInspector();

        // HEAP: these objects are allocated on the heap, shared across threads.
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        log.info(() -> "Created heap objects: " + rajesh.getAccountId() + ", " + priya.getAccountId());

        inspector.report("After creating 2 accounts");

        // YOUNG GEN pressure: create many short-lived objects that die young.
        List<String> garbage = new ArrayList<>();
        for (int i = 0; i < 100_000; i++) {
            garbage.add("txn-" + i);   // short-lived strings, mostly collected from Young Gen
        }
        garbage.clear();               // now eligible for garbage collection
        inspector.report("After creating & releasing 100k temp objects");

        // STACK: nested method calls each push a new frame on this thread's stack.
        TransferService service = new TransferService();
        service.transfer(rajesh, priya, new BigDecimal("50000"));

        inspector.report("After transfer");
    }
}

