package com.bank.jvm;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// Contrasts frequent fast Minor GC with rare slow Major/Full GC.
public class GCContrastDemo {
    private static final Logger log = Logger.getLogger(GCContrastDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    // A deliberately leaking cache: entries are added and never removed -> Old Gen grows.
    private static final List<byte[]> leakyCache = new ArrayList<>();

    public static void main(String[] args) {
        GCMonitor monitor = new GCMonitor();
        monitor.snapshot("Start");

        // PHASE 1: high churn -> many Minor GCs, objects die young.
        log.info("Phase 1: high churn (expect MANY Minor GCs)");
        for (int i = 0; i < 2_000_000; i++) {
            OrderEvent e = new OrderEvent("ORD-" + i, new BigDecimal("50000"));
            if (e.getAmount().signum() < 0) leakyCache.add(new byte[0]); // never true; keeps JIT honest
        }
        monitor.snapshot("After Phase 1 (churn)");

        // PHASE 2: leak -> promote objects to Old Gen until a Major/Full GC fires.
        log.info("Phase 2: simulated leak (expect Major/Full GC, longer pause)");
        try {
            for (int i = 0; i < 2000; i++) {
                leakyCache.add(new byte[256 * 1024]); // 256KB each, survives -> Old Gen pressure
            }
        } catch (OutOfMemoryError oom) {
            log.severe("Heap exhausted by leak: " + oom.getMessage());
        }
        monitor.snapshot("After Phase 2 (leak)");
    }
}

