        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        HeapTrendMonitor monitor = new HeapTrendMonitor();

        try {
            long txnId = 0;
            while (true) {
                // Each "transfer" creates an audit record...
                AuditRecord rec = new AuditRecord("TXF-" + txnId,
                        "SAV2001", "CUR3001", new BigDecimal("50000"));
                // ...and LEAKS it into a static cache that is never pruned.
