class TimingHarness {
    private static final Logger log = Logger.getLogger(TimingHarness.class.getName());
    private static final BigDecimal PRINCIPAL = new BigDecimal("1000000");
    private static final BigDecimal RATE = new BigDecimal("0.065");

    // Call the hot method many times just to trigger JIT compilation.
    void warmUp(InterestCalculator calc, int iterations) {
        BigDecimal sink = BigDecimal.ZERO;
        for (int i = 0; i < iterations; i++) {
            sink = sink.add(calc.calculateInterest(PRINCIPAL, RATE));
        }
        log.fine(() -> "warm-up sink=" + sink); // consume result so it is not optimized away
    }

    // Measure how many operations complete in a fixed window; consume the result.
    long measure(InterestCalculator calc, int iterations, String label) {
        BigDecimal sink = BigDecimal.ZERO;
        long start = System.nanoTime();
        for (int i = 0; i < iterations; i++) {
            sink = sink.add(calc.calculateInterest(PRINCIPAL, RATE));
        }
        long elapsedMs = (System.nanoTime() - start) / 1_000_000;
        long opsPerMs = elapsedMs == 0 ? iterations : iterations / elapsedMs;
        log.info(String.format("%-24s iterations=%d elapsed=%dms opsPerMs=%d (sink=%s)",
                label, iterations, elapsedMs, opsPerMs, sink.signum()));
        return opsPerMs;
    }
