        Account a = new Account("SAV2001", new BigDecimal("1000000"));
        Account b = new Account("CUR3001", new BigDecimal("250000"));
        SafeTransferService safe = new SafeTransferService();
        Thread s1 = new Thread(() -> safe.transfer(a, b, new BigDecimal("50000")), "safe-A-to-B");
        Thread s2 = new Thread(() -> safe.transfer(b, a, new BigDecimal("30000")), "safe-B-to-A");
        s1.start(); s2.start(); s1.join(); s2.join();
        log.info("SAFE transfers both completed with no deadlock");
        detector.stop();
