        // --- STARVATION: tiny pool, slow tasks hog all threads ---
        ThreadPoolExecutor tiny = new ThreadPoolExecutor(
                2, 2, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>());
        PoolInspector inspector = new PoolInspector();

        for (int i = 0; i < 20; i++) tiny.submit(new TransferTask("TXF-" + i)); // slow, fills pool
        long submitted = System.currentTimeMillis();
        Future<Long> check = tiny.submit(new BalanceCheckTask("SAV2001")); // quick but STARVED
        inspector.report("tiny pool", tiny);
        long waitedMs = check.get() + (System.currentTimeMillis() - submitted);
        log.warning("STARVED: quick balance check waited ~" + waitedMs + "ms behind slow transfers");
        tiny.shutdownNow();

        // --- FIX: right-sized pool + separate fast lane for quick tasks ---
        ThreadPoolExecutor slowLane = new ThreadPoolExecutor(
                8, 8, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>());
        ThreadPoolExecutor fastLane = new ThreadPoolExecutor(
                4, 4, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>());
        for (int i = 0; i < 20; i++) slowLane.submit(new TransferTask("TXF-" + i));
        long t0 = System.currentTimeMillis();
        long bal = fastLane.submit(new BalanceCheckTask("SAV2001")).get();
        log.info("FIXED: quick balance check returned " + bal
                + " in ~" + (System.currentTimeMillis() - t0) + "ms (fast lane)");
        slowLane.shutdownNow(); fastLane.shutdownNow();
    }
